widget.solution:
def umax_unbiased(sample):
    """(n + 1)/n times the largest value."""
    n = len(sample)
    return (n + 1) / n * max(sample)


def mse_divisor(n, d):
    """MSE of the sum of squared deviations over d, for normal data with variance 1."""
    k = n - 1
    return (2 * k + (k - d) ** 2) / d ** 2


def best_divisor(n):
    """The whole number d with the smallest mse_divisor(n, d)."""
    return min(range(1, 3 * n + 1), key=lambda d: mse_divisor(n, d))
